7: pub struct Sphere {
8:     pub center: Vec3,
9:     pub radius: f64,
10: }
11: 
12: impl Sphere {
13:     pub fn new(center: Vec3, radius: f64) -> Self {
14:         Sphere { center, radius }
15:     }
16: }
17: 
18: impl Hittable for Sphere {
19:     fn hit(&self, ray: &Ray, t_min: f64, t_max: f64) -> Option<HitRecord> {
20:         let oc = ray.origin - self.center;
21:         let a = ray.direction.dot(ray.direction);
22:         let half_b = oc.dot(ray.direction);
23:         let c = oc.dot(oc) - self.radius * self.radius;
24:         let discriminant = half_b * half_b - a * c;
25:         if discriminant < 0.0 {
26:             return None;
27:         }
28:         let root = discriminant.sqrt();
29:         let mut t = (-half_b - root) / a;
30:         if t <= t_min || t >= t_max {
31:             t = (-half_b + root) / a;
32:             if t <= t_min || t >= t_max {
33:                 return None;
34:             }
35:         }
36:         let point = ray.at(t);
37:         Some(HitRecord {
38:             t,
39:             point,
40:             normal: (point - self.center) / self.radius,
41:         })
42:     }
43: }
